7	  TRIGGERS, TRIGGER_SCHEDULE, TRIGGER_REQUEST,
8	} from '../../claudinite-tasks/task-contract.mjs';
9	import { validatePreconditions, termsMap, preconditionNeedsItem } from '../../claudinite-tasks/precondition-policy.mjs';
10	import {
11	  TASK_DECLARATION_PATH_RE, isLegacyTaskDeclarationPath, readDeclarationFields,
12	} from '../../claudinite-tasks/task-declaration-text.mjs';
13	
14	// Every scheduler task is a `tasks/<name>/task.json` carrying the declaration
15	// contract (per-project-scheduling DESIGN §1) with legal enum values. This
16	// asserts that shape statically at author time — the executor and scheduler
17	// validate the same contract at run time (task-contract.mjs), so an illegal
18	// condition/model/outcome, or a missing field, is caught here first.
19	//
20	// RELEVANCE FIRST (engine/checks/README.md): gated on a task declaration file
21	// existing, so the check is inert on any repo without tasks. Static text over the
22	// self-contained file — a `task.json` parsed whole, the retired `task.mjs` lifted
23	// by pattern — keyed off the canonical enum lists so the legal values never drift
24	// from the runtime validator.
25	
26	// The term names the task's own `preconditions.mjs` exports, read as text: the
27	// check runs over a file listing, not a module graph, so it recognises a
28	// task-local condition by the key that defines it. A term the file computes
29	// rather than spells is not found, and its declaration reads as unknown — which
30	// is the same "write it so a reader can see it" the literal rule above states.
31	// Read as TEXT, never imported: a check must not execute a member's own module. So
32	// each term is its name plus the one property of it a declaration can be wrong
33	// about — `needsItem`, which decides whether the term can be judged at a tick at
34	// all. Either quote style, because a member's file is its author's.
35	const TERM_NAME = /^ {2}['"]([^'"]+)['"]:/gm;
36	function siblingTerms(ctx, taskFile) {
37	  const text = ctx.read(taskFile.replace(/task\.(json|mjs)$/, 'preconditions.mjs'));
38	  if (text === null) return new Map();
39	  const body = stripComments(text);
40	  const start = body.indexOf('export const terms');
41	  if (start === -1) return new Map();
42	  const section = body.slice(start);
43	  const named = [...section.matchAll(TERM_NAME)];
44	  return termsMap(Object.fromEntries(named.map((m, i) => {
45	    const block = section.slice(m.index, named[i + 1]?.index ?? section.length);
46	    return [m[1], { signals: [], needsItem: /\bneedsItem\s*:\s*true\b/.test(block) }];
47	  })));
48	}
