50	// A file that only re-exports another module declares nothing of its own — a
51	// legacy-path shim left behind by a relocation is the shape. The declaration it
52	// names is scanned where it actually lives, so judging the shim would report the
53	// same task twice and fail it on text it does not carry.
54	const isReExport = (text) => {
55	  const code = text.split('\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('//'));
56	  return code.length > 0 && code.every((l) => /^(import|export)\b.*\bfrom\b/.test(l) || /^import\s+['"]/.test(l));
57	};
58	
59	const rule = {
60	  id: 'task-declaration-shape',
61	  severity: 'blocking',
62	  description: 'A tasks/<name>/task.json carries the task contract (id, description, preconditions, expected_outcome) with legal enum values and a well-formed precondition expression stating when the task runs; an agentic task names its worker file and bounds its run, and any code_work carries a timeout and stays task-local',
63	  doc: 'packs/claudinite-tasks/README.md',
64	  why: 'the scheduler run and executor read agent_model/expected_outcome/preconditions from this file, not the work item — an illegal or missing value means a task never fires, fires wrong, or writes past its ceiling',
65	
66	  run(ctx) {
67	    const out = [];
68	    for (const file of ctx.files.filter((f) => TASK_DECLARATION_PATH_RE.test(f))) {
69	      const text = ctx.read(file);
70	      if (text === null) continue;
71	      const flag = (what, fix) => out.push(finding(rule, { file, what, fix }));
72	      const advise = (what, fix) => out.push(finding(rule, { file, severity: 'advisory', what, fix }));
73	
74	      const legacy = isLegacyTaskDeclarationPath(file);
75	      if (legacy) {
76	        if (isReExport(text)) continue;
77	        // ADVISORY, like every other retired spelling here: the runtime still loads
78	        // the module form, and a member's vendor refresh must not turn its CI red
79	        // over a file nothing has converted yet. The nightly update converts a
80	        // member's own; this finding names the edit for anyone editing sooner.
81	        advise('is a task.mjs, the retired module form of a task declaration',
82	          'convert it to task.json — node <engine>/migrations/task-declarations-to-json.mjs rewrites every task.mjs under the repo\'s packs and deletes the module');
83	        if (!/export\s+default\s*\{/.test(text)) {
84	          flag('does not default-export a declaration object', 'convert it to a task.json carrying { id, description, preconditions, expected_outcome, … }');
85	          continue;
86	        }
87	      }
88	      const decl = readDeclarationFields(file, legacy ? stripComments(text) : text);
89	      if (decl.error) {
