146	      const model = declaredModel ?? DEFAULT_AGENT_MODEL;
147	
148	      // expected_outcome takes the ceiling/policy split, with the retired
149	      // one-word ceilings an ADVISORY rename like the code-work names below:
150	      // the runtime normalizes them at the door forever, so a member's vendor
151	      // refresh must not turn its CI red over a declaration nobody edited.
152	      const outcome = str('expected_outcome');
