20	  // counts dispatches, not outcomes (Sheepdog#172), so a wrong id here is invisible.
21	  // Searched across every pack rather than pinned to the one that happens to own
22	  // it today: the scheduler discovers tasks by scanning each ACTIVE pack's
23	  // `tasks/`, so which pack holds `update` is not this lever's business and has
24	  // already changed once (#835 moved it from basics to core). Naming a pack here
25	  // would go red on a move that is invisible to the dispatch, and the failure it
26	  // must actually catch — no pack owns this id at all — is the one below.
27	  const owners = readdirSync(join(ROOT, 'packs'), { withFileTypes: true })
28	    .filter((d) => d.isDirectory())
29	    .filter((d) => existsSync(join(ROOT, 'packs', d.name, 'tasks', FORCED_TASK, 'task.json')))
30	    .map((d) => d.name);
