36	// --- the repos filter ----------------------------------------------------------
37	
38	test('parseRepoFilter: space-separated, owner-qualified, lowercased; empty means everyone', () => {
39	  assert.equal(parseRepoFilter('', 'acme'), null);
40	  assert.equal(parseRepoFilter(undefined, 'acme'), null);
41	  const f = parseRepoFilter('Alpha  acme/Beta', 'acme');
42	  assert.deepEqual([...f].sort(), ['acme/alpha', 'acme/beta']);
43	});
44	
45	// --- scope classification -------------------------------------------------------
46	
47	const repo = (over = {}) => ({ full_name: 'acme/app', archived: false, fork: false, ...over });
48	const ctx = (over = {}) => ({ canonRepo: 'acme/Claudinite', exclude: new Set(), filter: null, ...over });
49	
