51	  assert.equal(classifyScope(repo(), ctx()), null);
52	  assert.equal(classifyScope(repo({ full_name: 'acme/Claudinite' }), ctx()).state, 'canon');
53	  assert.equal(classifyScope(repo({ archived: true }), ctx()).state, 'out-of-scope');
54	  assert.equal(classifyScope(repo({ fork: true }), ctx()).state, 'out-of-scope');
55	  assert.equal(classifyScope(repo(), ctx({ exclude: new Set(['acme/app']) })).state, 'excluded');
56	  assert.equal(classifyScope(repo(), ctx({ filter: new Set(['acme/other']) })).state, 'filtered-out');
57	  assert.equal(classifyScope(repo(), ctx({ filter: new Set(['acme/app']) })), null);
58	});
