for f in packs/chrome-extension/test/tasks.test.mjs packs/claudinite-canon-curation/test/tasks.test.mjs packs/claudinite-growth/test/tasks.test.mjs packs/claudinite-lifecycle/test/tasks.test.mjs packs/claudinite-fleet-sheepdog/test/tasks/fleet-baseline/task.test.mjs packs/claudinite-fleet-sheepdog/test/tasks/fleet-roster/task.test.mjs packs/claudinite-fleet-sheepdog/test/tasks/fleet-add-missing-packs/task.test.mjs packs/claudinite-fleet-sheepdog/test/tasks/fleet-pack-seeds/task.test.mjs packs/product-wiki/test/pack.test.mjs packs/tidy-repo/test/skills/improve-comments/checks.test.mjs packs/claudinite-dashboard/test/tasks/publish-pages/worker.test.mjs; do
